CREATE FUNCTION public.signal_note_count(_id uuid) RETURNS bigint LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$SELECT count(*) FROM opportunity_signal_notes n JOIN opportunity_signals s ON s.id=n.signal_id WHERE s.id=_id AND signal_note_is_progression(n.note,n.event_type,n.is_progression)$$;REVOKE ALL ON FUNCTION signal_note_count(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION signal_note_count(uuid) TO authenticated;
DO $$DECLARE j bigint;BEGIN FOR j IN SELECT jobid FROM cron.job WHERE jobname='signal-progression-daily' LOOP PERFORM cron.unschedule(j);END LOOP;END$$;